// Copies brand assets from <repo>/brand into the site so they cannot drift.
// brand/ stays the only place they are edited. The copies are git-ignored and are
// regenerated by `npm run build` / `npm start` (via the `sync` script).
//
//   brand/logo/aiplex-lockup-horizontal.svg           -> static/img/aiplex-logo.svg
//   brand/logo/aiplex-lockup-horizontal-reversed.svg  -> static/img/aiplex-logo-dark.svg
//   brand/logo/aiplex-favicon.svg                     -> static/img/favicon.svg
//   brand/tokens/tokens.css                           -> src/css/brand-tokens.css
//   brand/icons/*.svg                                 -> src/brand/icons/ (imported as React components)
//   brand/{logo,icons,social,brand-sheet.svg}         -> static/img/brand/ (for the Brand page)
//
// The social card PNG (static/img/aiplex-social-card.png) is committed, not copied;
// see docs-site/README.md for how to regenerate it.
import {promises as fs} from 'node:fs';
import path from 'node:path';
import {fileURLToPath} from 'node:url';

const siteRoot = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const brand = path.resolve(siteRoot, '..', 'brand');

async function copy(from, to) {
  await fs.mkdir(path.dirname(to), {recursive: true});
  await fs.copyFile(path.join(brand, from), path.join(siteRoot, to));
}

async function copyDir(dir, toDir) {
  for (const f of await fs.readdir(path.join(brand, dir))) {
    if (f.endsWith('.svg')) await copy(`${dir}/${f}`, `${toDir}/${f}`);
  }
}

await fs.rm(path.join(siteRoot, 'static/img/brand'), {recursive: true, force: true});
await fs.rm(path.join(siteRoot, 'src/brand'), {recursive: true, force: true});

await copy('logo/aiplex-lockup-horizontal.svg', 'static/img/aiplex-logo.svg');
await copy('logo/aiplex-lockup-horizontal-reversed.svg', 'static/img/aiplex-logo-dark.svg');
await copy('logo/aiplex-favicon.svg', 'static/img/favicon.svg');
await copy('tokens/tokens.css', 'src/css/brand-tokens.css');
await copyDir('icons', 'src/brand/icons');
await copyDir('logo', 'static/img/brand/logo');
await copyDir('icons', 'static/img/brand/icons');
await copyDir('social', 'static/img/brand/social');
await copy('brand-sheet.svg', 'static/img/brand/brand-sheet.svg');
console.log('sync-brand: brand assets copied');
